type OrderPlaced struct{ OrderID int64; OccurredAt time.Time }

func (OrderPlaced) EventName() string { return "order.placed" }

type Event interface{ EventName() string }

func (b *Bus) Publish(e Event) error {
    for _, h := range b.subs[e.EventName()] {   // subs guarded by RWMutex
        if err := h(e); err != nil { return err }  // fail fast, or collect all
    }
    return nil
}

