type Handler[T Event] interface{ Handle(context.Context, T) error }

func ListenOn[T Event](b *Bus, h Handler[T]) {
    var zero T
    b.register(reflect.TypeOf(zero), func(ctx context.Context, e Event) error {
        return h.Handle(ctx, e.(T))
    })
}
